@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1104  cases=34
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-128
  @fn seedItems(h, takes, srcLen)  @ 144-149
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 151-160

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 164-172
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 175-184
  @case 'focusState before any render returns both bits false'  [harness]  @ 187-194
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 200-213
  @case 'with no live instance, new take and unpooled duplicate mint a parked slot and select it'  [harness]  @ 217-239
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 245-266
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 272-290
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 297-315
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 321-354
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 358-382
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 388-418
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 422-443
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 447-460
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 466-500
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 504-518
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 522-545
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 552-569
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 573-596
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 600-623
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 627-662
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 666-682
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 689-716
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 720-744
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 751-772
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 778-796
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 800-818
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 822-844
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 848-872
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 878-933
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 941-970
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 976-1019
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1025-1039
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1046-1078
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1082-1102

